This issue has always been present, but has been latent until commit
"f9f4fda15e72" ("pinctrl: mcp23s08: init reg_defaults from HW at probe and
switch cache type"), which correctly removed reg_defaults from the regmap
and as a side effect changed the behavior of the interrupt handler so that
the real value of the MCP_GPINTEN register is now being read from the chip
instead of using a bogus 0 default value; a non-zero value for this
register can trigger the invocation of a nested handler which may not exist
(yet).
Fix this issue by disabling all pin interrupts during initialization.

Fixes: f9f4fda15e72 ("pinctrl: mcp23s08: init reg_defaults from HW at probe and switch cache type")
Signed-off-by: Francesco Lavra <flavra@baylibre.com>
Signed-off-by: Linus Walleij <linusw@kernel.org>

Here is the root cause:
During probe, the chip may retain interrupt-on-change enabled on some pins from a previous state (e.g., after reboot). The driver does not disable these interrupts before setting up the interrupt controller, so when an interrupt fires for a pin without a registered nested handler, the interrupt handler attempts to call a null handler, causing a kernel crash (NULL pointer dereference).

Here is the patch:

 int mcp23s08_probe_one(struct mcp23s08 *mcp, struct device *dev,
 		       unsigned int addr, unsigned int type, unsigned int base)
 {
 	int status, ret;
 	bool mirror = false;
 	bool open_drain = false;

 	mutex_init(&mcp->lock);

 	mcp->dev = dev;
 	mcp->addr = addr;

 	mcp->irq_active_high = false;

 	mcp->chip.direction_input = mcp23s08_direction_input;
 	mcp->chip.get = mcp23s08_get;
 	mcp->chip.get_multiple = mcp23s08_get_multiple;
 	mcp->chip.direction_output = mcp23s08_direction_output;
 	mcp->chip.set = mcp23s08_set;
 	mcp->chip.set_multiple = mcp23s08_set_multiple;

 	mcp->chip.base = base;
 	mcp->chip.can_sleep = true;
 	mcp->chip.parent = dev;
 	mcp->chip.owner = THIS_MODULE;

 	mcp->reset_gpio = devm_gpiod_get_optional(dev, "reset", GPIOD_OUT_LOW);

 	/* verify MCP_IOCON.SEQOP = 0, so sequential reads work,
 	 * and MCP_IOCON.HAEN = 1, so we work with all chips.
 	 */

 	ret = mcp_read(mcp, MCP_IOCON, &status);
 	if (ret < 0)
 		return dev_err_probe(dev, ret, "can't identify chip %d\n", addr);

 	mcp->irq_controller =
 		device_property_read_bool(dev, "interrupt-controller");
 	if (mcp->irq && mcp->irq_controller) {
 		mcp->irq_active_high =
 			device_property_read_bool(dev,
 					      "microchip,irq-active-high");

 		mirror = device_property_read_bool(dev, "microchip,irq-mirror");
 		open_drain = device_property_read_bool(dev, "drive-open-drain");
 	}

 	if ((status & IOCON_SEQOP) || !(status & IOCON_HAEN) || mirror ||
 	     mcp->irq_active_high || open_drain) {
 		/* mcp23s17 has IOCON twice, make sure they are in sync */
 		status &= ~(IOCON_SEQOP | (IOCON_SEQOP << 8));
 		status |= IOCON_HAEN | (IOCON_HAEN << 8);
 		if (mcp->irq_active_high)
 			status |= IOCON_INTPOL | (IOCON_INTPOL << 8);
 		else
 			status &= ~(IOCON_INTPOL | (IOCON_INTPOL << 8));

 		if (mirror)
 			status |= IOCON_MIRROR | (IOCON_MIRROR << 8);

 		if (open_drain)
 			status |= IOCON_ODR | (IOCON_ODR << 8);

 		if (type == MCP_TYPE_S18 || type == MCP_TYPE_018)
 			status |= IOCON_INTCC | (IOCON_INTCC << 8);

 		ret = mcp_write(mcp, MCP_IOCON, status);
 		if (ret < 0)
 			return dev_err_probe(dev, ret, "can't write IOCON %d\n", addr);
 	}

 	if (mcp->irq && mcp->irq_controller) {
 		struct gpio_irq_chip *girq = &mcp->chip.irq;

+		/*
+		 * Disable all pin interrupts, to prevent the interrupt handler from
+		 * calling nested handlers for any currently-enabled interrupts that
+		 * do not (yet) have an actual handler.
+		 */
+		ret = mcp_write(mcp, MCP_GPINTEN, 0);
+		if (ret < 0)
+			return dev_err_probe(dev, ret, "can't disable interrupts\n");
+
 		gpio_irq_chip_set_chip(girq, &mcp23s08_irq_chip);
 		/* This will let us handle the parent IRQ in the driver */
 		girq->parent_handler = NULL;
 		girq->num_parents = 0;
 		girq->parents = NULL;
 		girq->default_type = IRQ_TYPE_NONE;
 		girq->handler = handle_simple_irq;
 		girq->threaded = true;
 	}

 	ret = devm_gpiochip_add_data(dev, &mcp->chip, mcp);
 	if (ret < 0)
 		return dev_err_probe(dev, ret, "can't add GPIO chip\n");

 	mcp->pinctrl_desc.pctlops = &mcp_pinctrl_ops;
 	mcp->pinctrl_desc.confops = &mcp_pinconf_ops;
 	mcp->pinctrl_desc.npins = mcp->chip.ngpio;
 	if (mcp->pinctrl_desc.npins == 8)
 		mcp->pinctrl_desc.pins = mcp23x08_pins;
 	else if (mcp->pinctrl_desc.npins == 16)
 		mcp->pinctrl_desc.pins = mcp23x17_pins;
 	mcp->pinctrl_desc.owner = THIS_MODULE;

 	mcp->pctldev = devm_pinctrl_register(dev, &mcp->pinctrl_desc, mcp);
 	if (IS_ERR(mcp->pctldev))
 		return dev_err_probe(dev, PTR_ERR(mcp->pctldev), "can't register controller\n");

 	if (mcp->irq) {
 		ret = mcp23s08_irq_setup(mcp);
 		if (ret)
 			return dev_err_probe(dev, ret, "can't setup IRQ\n");
 	}

 	return 0;
 }
 EXPORT_SYMBOL_GPL(mcp23s08_probe_one);


